Given the root of a Binary Search Tree (BST), find the minimum value present in the tree.Example: Input: Output: 1Explanation: The minimum element in the given BST is 1.Input: Output: 2Explanation: The minimum element in the given BST is 2Try It YourselfTable of Content[Naive Approach] Using Inorder Traversal - O(n) Time and O(n) Space[Better Approach] Using Recursion - O(h) Time and O(h) Space[Expected Approach] Using Iterative Way - O(h) Time and O(1) Space[Naive Approach] Using Inorder Traversal - O(n) Time and O(n) SpaceThe idea is to use the property of BST which says inorder traversal of a binary search tree always returns the value of nodes in sorted order. So the 1st value in the sorted vector will be the minimum value which is the answer.
            C++

    //Driver Code Starts
#include <iostream>
#include<vector>
using namespace std;

// Node structure
class Node {
public:
    int data;
    Node *left, *right;

    Node(int val) {
        data = val;
        left = right = nullptr;
    }
};
//Driver Code Ends


// Performs inorder traversal of BST 
// and stores values in sorted order
void inorder(Node* root, vector<int>& sortedInorder) {

    // Base Case
    if (root == nullptr) return;

    // Traverse left subtree
    inorder(root->left, sortedInorder);

    sortedInorder.push_back(root->data);

    // Traverse right subtree
    inorder(root->right, sortedInorder);
}

// Returns the minimum value in a BST
int minValue(Node* root) {
    if (root == nullptr) {
        return -1;
    }

    vector<int> sortedInorder;

    // Get all BST values in sorted order
    inorder(root, sortedInorder);

    return sortedInorder[0];
}


//Driver Code Starts
int main() {

    // Create BST
    //        5
    //       / \
    //      4   6
    //     /     \
    //    3       7
    //   / 
    //  1
    Node* root = new Node(5);
    root->left = new Node(4);
    root->right = new Node(6);
    root->left->left = new Node(3);
    root->right->right = new Node(7);
    root->left->left->left = new Node(1);

    cout << minValue(root) << "
";

    return 0;
}

